/**
 * Contrast and colour-blindness audit of the theme tokens (src/styles/palette.css, generated by
 * scripts/palette.ts; src/styles/tokens.css; and the High contrast overrides in
 * src/styles/accessibility.css).
 *
 * Every colour pair the app actually draws is listed in PAIRS by token (any new colour pair goes
 * there too, CLAUDE.md), so a
 * changed token is re-checked automatically; every element, rarity and Home tone gets its
 * pairs from the palette's SWATCHES. Translucent colours and element
 * opacity are composited over what they sit on. Colour blindness uses the
 * Machado et al. (2009) matrices at full severity.
 *
 *   node scripts/contrast.ts            print the full table
 *   node --test test/contrast.test.ts   fail on any regression
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { PLATE_OPACITY, SWATCHES, lightFill } from './palette.ts';

/** Each theme, and each with Setup > Accessibility > Contrast: High. */
export type Theme = 'dark' | 'light' | 'dark-hc' | 'light-hc';
type RGBA = [number, number, number, number];

/** [label, foreground token, background token, required ratio, what a translucent background sits on, foreground opacity] */
type Pair = [string, string, string, number, string?, number?];

