/** The surfaces a swatch's ink, line and mark must hold up on. */
const SURFACES: [string, string][] = [['page', '--bg'], ['surface', '--surface'], ['surface-2', '--surface-2'], ['modal', '--modal-bg']];
for (const { id } of SWATCHES) {
  PAIRS.push([`${id}: on-fill`, `--${id}-on`, `--${id}-fill`, 4.5]);
  for (const [n, t] of SURFACES) PAIRS.push([`${id}: ink on ${n}`, `--${id}-ink`, t, 4.5]);
  for (const [n, t] of SURFACES) PAIRS.push([`UI: ${id} line vs ${n}`, `--${id}-line`, t, 3]);
  for (const [n, t] of SURFACES) PAIRS.push([`UI: ${id} mark vs ${n}`, `--${id}-mark`, t, 3]);
  PAIRS.push([`${id}: text on wash (card)`, '--text', `--${id}-wash`, 4.5, '--surface']);
  PAIRS.push([`${id}: text on wash (page)`, '--text', `--${id}-wash`, 4.5, '--bg']);
  PAIRS.push([`${id}: ink on wash (card)`, `--${id}-ink`, `--${id}-wash`, 4.5, '--surface']);
}
/**
 * Where a name plate is drawn: Home and the leaderboard on the page, Profile, Forge cards, the
 * plate sheet, and a chosen card or your own row (its own step, --plate-*-chosen). Measured on
 * the solid line: the wear mask takes specks out of it, not its colour.
 */
const PLATE_SURFACES: [string, string, string?][] = [['page', '--bg'], ['surface', '--surface'], ['surface-2', '--surface-2'], ['profile', '--profile-bg'], ['modal', '--modal-bg']];
for (const metal of ['bronze', 'silver', 'gold', 'diamond', 'elo']) {
  for (const [n, t] of PLATE_SURFACES) PAIRS.push([`UI: ${metal} plate vs ${n}`, `--plate-${metal}`, t, 3, undefined, PLATE_OPACITY]);
  PAIRS.push([`UI: ${metal} plate vs a chosen card`, `--plate-${metal}-chosen`, '--chosen-bg', 3, '--surface', PLATE_OPACITY]);
}
// Ranked rank names (ranks.css): both ends of each rank's gradient are text, on every surface a
// rank is written on, your own row and the Ranks sheet's chosen line included; the Ranks sheet's
// share bar fills with the deeper end on its track
for (let i = 0; i < 5; i++) {
  for (const end of ['hi', 'lo']) {
    for (const [n, t] of PLATE_SURFACES) PAIRS.push([`rank ${i} name (${end}) on ${n}`, `--rank-${i}-${end}`, t, 4.5]);
    PAIRS.push([`rank ${i} name (${end}) on a chosen row`, `--rank-${i}-${end}`, '--chosen-bg', 4.5, '--surface']);
  }
  PAIRS.push([`UI: rank ${i} share bar vs its track`, `--rank-${i}-lo`, '--surface', 3]);
}
// the leaderboard's medals (and the top-100 underline) are the plate metals, checked above; on
// your own row they take the chosen step too
for (const metal of ['bronze', 'silver', 'gold'])
  PAIRS.push([`UI: ${metal} medal on your row`, `--plate-${metal}-chosen`, '--chosen-bg', 3, '--surface']);

/**
 * Pairs that may stay under their ratio, and why. Anything else failing is a regression. A key
 * is a label, or `theme: label` for one theme only (accepted(), below).
 */
export const ACCEPTED: Record<string, string> = {
  'UI: board cell vs page': 'the 3x3 box outline (--grid-line) carries the board structure',
  'UI: row/column highlight vs cell': 'supplementary; the selection ring marks the cell (High contrast makes it strong)',
  'UI: same-number fill vs cell': 'supplementary; the number itself is the cue',
  'UI: action button vs page': 'buttons are identified by their text label',
  'UI: modal border': 'decorative hairline',
  'UI: mistake unused vs page': 'an empty slot: used skulls (Lava, 3:1 and scaled up) carry the count, the row label says it, and High contrast fills the slots in --muted',
  'UI: selection ring vs same-number fill': 'light theme: the inner ring (--select-inner) carries it there',
};
// The deep fills keep their Figma depth on the dark theme: as bare shapes there (a ring, a dot,
// a bar segment) they sit under 3:1, as Lava always has. On the light theme they must pass.
for (const s of SWATCHES.filter((s) => !lightFill(s)))
  for (const theme of ['dark', 'dark-hc'])
    for (const [n] of SURFACES)
      ACCEPTED[`${theme}: UI: ${s.id} mark vs ${n}`] =
        'a deep fill as a shape always sits beside its name or crest; where a shape alone must be seen, the line role is 3:1';

// Name plates are see-through (PLATE_OPACITY, owner 2026-10-21): measured as drawn, and allowed
// under 3:1 there, since a plate is decoration under a name that is always written. (High
// contrast draws them solid; measured at the same opacity here, so on the safe side.)
for (const metal of ['bronze', 'silver', 'gold', 'diamond', 'elo'])
  for (const n of [...PLATE_SURFACES.map(([n]) => n), 'a chosen card'])
    ACCEPTED[`UI: ${metal} plate vs ${n}`] = 'decoration under the name, which is always written; see-through by design';

/** Why a pair may stay under its ratio in this theme, or undefined. */
export const accepted = (theme: string, label: string): string | undefined => ACCEPTED[`${theme}: ${label}`] ?? ACCEPTED[label];

const lin = (v: number) => {
  v /= 255;
  return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
};
const luminance = (c: RGBA) => 0.2126 * lin(c[0]) + 0.7152 * lin(c[1]) + 0.0722 * lin(c[2]);
export const ratio = (a: RGBA, b: RGBA): number => {
  const [x, y] = [luminance(a), luminance(b)].sort((p, q) => q - p);
  return (x + 0.05) / (y + 0.05);
};
const over = (fg: RGBA, bg: RGBA): RGBA => [0, 1, 2].map((i) => fg[i] * fg[3] + bg[i] * (1 - fg[3])).concat(1) as RGBA;
const hex = (c: RGBA) => '#' + c.slice(0, 3).map((v) => Math.round(v).toString(16).padStart(2, '0')).join('');

function parse(c: string): RGBA | null {
  c = c.trim().toLowerCase();
  if (c === 'transparent') return null;
  let m = c.match(/^#([0-9a-f]{6})$/);
  if (m) return [0, 2, 4].map((i) => parseInt(m![1].slice(i, i + 2), 16)).concat(1) as RGBA;
  m = c.match(/^rgba?\(([^)]+)\)$/);
  if (m) {
    const p = m[1].split(',').map((x) => parseFloat(x));
    return [p[0], p[1], p[2], p[3] ?? 1];
  }
  throw new Error(`Unreadable colour: ${c}`);
}

/** Custom properties declared in every block matching `selector`, later blocks winning (the cascade). */
function block(css: string, selector: RegExp): Record<string, string> {
  const vars: Record<string, string> = {};
  const all = new RegExp(selector.source, selector.flags.includes('g') ? selector.flags : `${selector.flags}g`);
  const found = [...css.matchAll(all)];
  if (!found.length) throw new Error(`Block not found: ${selector}`);
  for (const m of found) {
    const start = css.indexOf('{', m.index!) + 1;
    let depth = 1;
    let i = start;
    while (depth) {
      if (css[i] === '{') depth++;
      else if (css[i] === '}') depth--;
      i++;
    }
    for (const d of css.slice(start, i - 1).matchAll(/(--[\w-]+)\s*:\s*([^;]+);/g)) vars[d[1]] = d[2].replace(/\/\*.*?\*\//g, '').trim();
  }
  return vars;
}

export function themes(css: string): Record<Theme, Record<string, string>> {
  // the plain :root blocks: the generated palette (palette.css) and the scales (tokens.css)
  const palette = block(css, /(?:^|\n)\s*(?:\/\*[^\n]*\*\/\s*)?:root\s*\{/);
  const dark = { ...palette, ...block(css, /:root,\s*:root\[data-theme='dark'\]/) };
  const light = { ...palette, ...block(css, /:root\[data-theme='light'\]\s*\{/) };
  // High contrast: the shared overrides, then each theme's own (styles.css, "High contrast").
  const hc = block(css, /:root\[data-contrast='high'\]\[data-theme\]\s*\{/);
  return {
    dark,
    light,
    'dark-hc': { ...dark, ...hc, ...block(css, /:root\[data-contrast='high'\]\[data-theme='dark'\]\s*\{/) },
    'light-hc': { ...light, ...hc, ...block(css, /:root\[data-contrast='high'\]\[data-theme='light'\]\s*\{/) },
  };
}

function resolve(vars: Record<string, string>, value: string): string {
  const ref = value.trim().match(/^var\((--[\w-]+)(?:,\s*(.+))?\)$/);
  if (!ref) return value.trim();
  const next = vars[ref[1]] ?? ref[2];
  if (next === undefined) throw new Error(`Unknown token ${ref[1]}`);
  return resolve(vars, next);
}

function colour(vars: Record<string, string>, token: string, under?: RGBA | null): RGBA | null {
  const c = parse(resolve(vars, `var(${token})`));
  if (!c || c[3] === 1) return c;
  return over(c, under ?? (parse(resolve(vars, 'var(--bg)')) as RGBA));
}

export interface Row {
  label: string;
  fg: string;
  bg: string;
  ratio: number;
  need: number;
  pass: boolean;
}

export function contrast(css: string): Record<Theme, Row[]> {
  const out = { dark: [], light: [], 'dark-hc': [], 'light-hc': [] } as Record<Theme, Row[]>;
  for (const [theme, vars] of Object.entries(themes(css)) as [Theme, Record<string, string>][]) {
    for (const [label, fgToken, bgToken, need, underToken, opacity] of PAIRS) {
      const under = underToken ? colour(vars, underToken) : undefined;
      const bg = colour(vars, bgToken, under);
      let fg = bg && colour(vars, fgToken, bg);
      if (!fg || !bg) continue; // a transparent token: nothing drawn in this theme
      if (opacity !== undefined) fg = over([fg[0], fg[1], fg[2], opacity], bg);
      const r = ratio(fg, bg);
      out[theme].push({ label, fg: hex(fg), bg: hex(bg), ratio: r, need, pass: r >= need });
    }
  }
  return out;
}

// --- Colour blindness ------------------------------------------------------

const MACHADO: Record<string, number[][]> = {
  protanopia: [[0.152286, 1.052583, -0.204868], [0.114503, 0.786281, 0.099216], [-0.003882, -0.048116, 1.051998]],
  deuteranopia: [[0.367322, 0.860646, -0.227968], [0.280085, 0.672501, 0.047413], [-0.01182, 0.04294, 0.968881]],
  tritanopia: [[1.255528, -0.076749, -0.178779], [-0.078411, 0.930809, 0.147602], [0.004733, 0.691367, 0.3039]],
};
const unlin = (v: number) => 255 * (v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055);
const simulate = (c: RGBA, m: number[][]): RGBA => {
  const l = [lin(c[0]), lin(c[1]), lin(c[2])];
  return m.map((row) => Math.min(255, Math.max(0, unlin(row[0] * l[0] + row[1] * l[1] + row[2] * l[2])))).concat(1) as RGBA;
};
function lab(c: RGBA): [number, number, number] {
  const [r, g, b] = [lin(c[0]), lin(c[1]), lin(c[2])];
  const xyz = [(0.4124 * r + 0.3576 * g + 0.1805 * b) / 0.95047, 0.2126 * r + 0.7152 * g + 0.0722 * b, (0.0193 * r + 0.1192 * g + 0.9505 * b) / 1.08883];
  const f = (t: number) => (t > 0.008856 ? Math.cbrt(t) : 7.787 * t + 16 / 116);
  const [fx, fy, fz] = xyz.map(f);
  return [116 * fy - 16, 500 * (fx - fy), 200 * (fy - fz)];
}
const deltaE = (a: RGBA, b: RGBA) => {
  const [x, y] = [lab(a), lab(b)];
  return Math.hypot(x[0] - y[0], x[1] - y[1], x[2] - y[2]);
};

/** Cell states compared pairwise under each kind of colour vision. */
export const STATES: [string, string][] = [
  ['cell', '--cell'],
  ['row/column highlight', '--cell-cross'],
  ['same number', '--same-bg'],
  ['wrong', '--wrong-bg'],
  ['hint', '--accent'],
];

export interface StatePair {
  vision: string;
  pair: string;
  deltaE: number;
}

/** State pairs that look alike (ΔE < 15) under some kind of colour vision. */
export function lookAlikes(css: string): Record<Theme, StatePair[]> {
  const out = { dark: [], light: [], 'dark-hc': [], 'light-hc': [] } as Record<Theme, StatePair[]>;
  for (const [theme, vars] of Object.entries(themes(css)) as [Theme, Record<string, string>][]) {
    const cols = STATES.map(([name, token]) => [name, colour(vars, token)!] as const);
    for (const vision of ['normal', ...Object.keys(MACHADO)]) {
      for (let i = 0; i < cols.length; i++) {
        for (let j = i + 1; j < cols.length; j++) {
          const see = (c: RGBA) => (vision === 'normal' ? c : simulate(c, MACHADO[vision]));
          const d = deltaE(see(cols[i][1]), see(cols[j][1]));
          if (d < 15) out[theme].push({ vision, pair: `${cols[i][0]} / ${cols[j][0]}`, deltaE: d });
        }
      }
    }
  }
  return out;
}

/** The whole stylesheet as one text: styles.css with each of its @imports (src/styles/*.css) in place. */
export const readStyles = (): string =>
  readFileSync(new URL('../src/styles.css', import.meta.url), 'utf8').replace(/^@import '\.\/(styles\/[\w-]+\.css)';$/gm, (_, file: string) =>
    readFileSync(new URL(`../src/${file}`, import.meta.url), 'utf8'));

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const css = readStyles();
  for (const [theme, rows] of Object.entries(contrast(css))) {
    console.log(`\n${theme}`);
    for (const r of rows) {
      const state = r.pass ? 'pass' : accepted(theme, r.label) ? 'ok* ' : 'FAIL';
      console.log(`${state}  ${r.ratio.toFixed(2).padStart(5)}:1  need ${r.need}  ${r.fg} on ${r.bg}  ${r.label}`);
    }
  }
  console.log('\nok* = below the ratio by design (ACCEPTED in this file)');
  for (const [theme, rows] of Object.entries(lookAlikes(css))) {
    console.log(`\n${theme}: cell states with ΔE < 15`);
    for (const r of rows) console.log(`${r.vision.padEnd(13)} ${r.pair.padEnd(34)} ΔE ${r.deltaE.toFixed(1)}`);
  }
}
